// notifications/OrderNotificationService.ts
import { PostgresOrderRepository } from '../order/infra/PostgresOrderRepository';
import { SendGridEmailClient } from '../email/infra/SendGridEmailClient';
import { SlackWebhookClient } from '../comms/infra/SlackWebhookClient';

export class OrderNotificationService {
  private orderRepo = new PostgresOrderRepository();
  private email = new SendGridEmailClient(process.env.SENDGRID_KEY!);
  private slack = new SlackWebhookClient(process.env.SLACK_URL!);

  async notifyOrderConfirmed(orderId: string): Promise<void> {
    const order = await this.orderRepo.findById(orderId);
    if (order.status === 1) { // 1 = confirmed
      await this.email.send(order.customerEmail, 'Order confirmed', `Order ${orderId} confirmed`);
      await this.slack.post(`#ops`, `Order ${orderId} confirmed for ${order.customerEmail}`);
    }
  }
}
